import { randomInt } from 'node:crypto';

const SEPARATOR = ':::';
const RANDOM_LENGTH = 20;

/**
 * Generates a unique tool call ID in format: {toolName}:::{random20chars}
 * This format allows easy parsing of tool name from callId.
 */
export function generateToolCallId(toolName: string): string {
  const chars = 'abcdefghijklmnopqrstuvwxyz';
  let random = '';
  for (let i = 0; i < RANDOM_LENGTH; i++) {
    random += chars.charAt(randomInt(chars.length));
  }
  return `${toolName}${SEPARATOR}${random}`;
}

/**
 * Parses tool name from a tool call ID generated by generateToolCallId.
 * Returns 'unknown' if the callId format is invalid.
 */
export function parseToolNameFromToolCallId(callId: string): string {
  const parts = callId.split(SEPARATOR);
  return parts[0] || 'unknown';
}
